Here's a simple HTML page that fetches and displays the current weather in San Francisco.

```html
<html>
<head>
    <title>San Francisco Weather</title>
    <script src="https://unpkg.com/axios/dist/axios.min.js"></script>
    <script>
        async function loadWeather() {
            const response = await axios.get('https://api.weatherapi.com/v1/current.json', {
                params: {
                    key: 'your_api_key',
                    q: 'San Francisco'
                }
            });
            const weather = response.data.current;
            document.getElementById('weather').innerHTML = `
                <p>Temperature: ${weather.temp_c}&deg;C</p>
                <p>Condition: ${weather.condition.text}</p>
            `;
        }
        window.onload = loadWeather;
    </script>
</head>
<body>
    <h1>San Francisco Weather</h1>
    <div id='weather'>Loading...</div>
</body>
</html>
```

