Here is a basic HTML form to input a city name and retrieve its current weather.

```html
<html>
<head>
    <title>Weather Checker</title>
</head>
<body>
    <h1>Check the Weather</h1>
    <form id='weatherForm'>
        <label for='city'>City:</label>
        <input type='text' id='city' name='city' required>
        <button type='submit'>Get Weather</button>
    </form>
    <div id='weatherOutput'></div>
    <script>
        document.getElementById('weatherForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const city = document.getElementById('city').value;
            fetch(`https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=YOUR_API_KEY`)
                .then(response => response.json())
                .then(data => {
                    const weatherOutput = document.getElementById('weatherOutput');
                    weatherOutput.innerHTML = `<p>The current temperature in ${city} is ${data.main.temp}°C.</p>`;
                })
                .catch(error => console.error('Error:', error));
        });
    </script>
</body>
</html>
```

