I have added a toggle button below the weather widget to switch between Celsius and Fahrenheit.

```html
<html>
  <head>
    <title>New York Weather</title>
  </head>
  <body>
    <h1>New York Weather</h1>
    <div id="weather"></div>
    <button onclick="toggleUnits()">Toggle Units</button>
    <script>
      let isCelsius = true;
      fetch('https://api.openweathermap.org/data/2.5/weather?q=New York&appid=your_api_key&units=metric')
        .then(response => response.json())
        .then(data => {
          updateWeather(data, isCelsius);
        });
      function updateWeather(data, celsius) {
        let temp = celsius ? data.main.temp : (data.main.temp * 9/5) + 32;
        document.getElementById('weather').innerHTML =
          `<p>Temperature: ${temp.toFixed(1)} &#8451;</p>
           <p>Description: ${data.weather[0].description}</p>`;
      }
      function toggleUnits() {
        isCelsius = !isCelsius;
        fetch('https://api.openweathermap.org/data/2.5/weather?q=New York&appid=your_api_key&units=' + (isCelsius ? 'metric' : 'imperial'))
          .then(response => response.json())
          .then(data => updateWeather(data, isCelsius));
      }
    </script>
  </body>
</html>
```

